-- AC datas : OLD Description : "", Description AC enUS : "" ; Wowhead enUS : "Speak to Seer Ravenfeather for another Earth Sapta."
UPDATE `quest_template_locale` SET `Details` = 'Sprecht mit Seherin Rabenfeder wegen eines weiteren Erdsaptas.', `VerifiedBuild` = 0 WHERE `locale` = 'deDE' AND `ID` = 1462;
