UPDATE `quest_template_locale` SET `Title` = 'Agammagans Beweglichkeit', `VerifiedBuild` = 0 WHERE `locale` = 'deDE' AND `ID` = 5043;
-- AC datas : OLD Title : "Weisheit von Agamaggan", Title AC enUS : "Wisdom of Agamaggan" ; Wowhead enUS : "Wisdom of Agamaggan"
