UPDATE `quest_template_locale` SET `Details` = 'Gebt Mokvar Eure Helmkappe der Elemente und Eure Weste der Elemente.', `VerifiedBuild` = 0 WHERE `locale` = 'deDE' AND `ID` = 9011;
