UPDATE `quest_template_locale` SET `Title` = NULL, `Details` = 'Diese Quest ist nicht mehr im Spiel verfügbar./wave at Kill Credit Test', `VerifiedBuild` = 0 WHERE `locale` = 'deDE' AND `ID` = 12911;

